SELECT CAST(SUM("PARTIAL_count_0") AS DECIMAL(18,0)), CAST(ROUND((SUM("PARTIAL_sum_1") / SUM("PARTIAL_count_0")), 2) AS DECIMAL(36,2)) FROM (SELECT LAKEHOUSE_SCAN('{"table_root":"s3://warehouse/db/events","projection":[],"aggregates":[{"kind":"count"},{"kind":"sum","column":"AMOUNT"}],"storage":{"connection":{"name":"LAKEHOUSE_CATALOG_CREDS","allow_http":true}},"df_target_partitions":4,"df_batch_size":8192,"df_threads_per_udf":2,"memory_pool_fraction":0.6,"instance_overhead_mb":200,"s3_max_connections":8}', files) EMITS ("PARTIAL_count_0" DECIMAL(20,0), "PARTIAL_sum_1" DECIMAL(36,2)) FROM (SELECT LAKEHOUSE_DISTRIBUTE_FILES(files) FROM (VALUES (0,'[["data/part-0.parquet",1000]]'),(1,'[["data/part-1.parquet",2000]]'),(2,'[["data/part-2.parquet",1500]]')) AS shards(shard_key, files) GROUP BY shard_key))